def match(orders):
    trades = []
    book = {'buy': [], 'sell': []}
    order_state = {}

    for order in orders:
        order_type = order[0]
        order_id = order[1]

        if order_type == 'cancel':
            if order_id in order_state and order_state[order_id]['status'] == 'resting':
                side = order_state[order_id]['side']
                book[side] = [o for o in book[side] if o['id'] != order_id]
                order_state[order_id]['status'] = 'cancelled'
            continue

        side = order[2]

        if order_type == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        order_state[order_id] = {
            'side': side,
            'price': price,
            'qty': qty,
            'status': 'active',
            'arrival_time': len(order_state)
        }

        opposite_side = 'sell' if side == 'buy' else 'buy'

        while qty > 0 and book[opposite_side]:
            if side == 'buy':
                resting = book['sell'][0]
                if price is not None and resting['price'] > price:
                    break
            else:
                resting = book['buy'][0]
                if price is not None and resting['price'] < price:
                    break

            trade_qty = min(qty, resting['qty'])
            trade_price = resting['price']

            if side == 'buy':
                trades.append([order_id, resting['id'], trade_price, trade_qty])
            else:
                trades.append([resting['id'], order_id, trade_price, trade_qty])

            qty -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                book[opposite_side].pop(0)
                order_state[resting['id']]['status'] = 'filled'
            else:
                order_state[resting['id']]['qty'] = resting['qty']

        if order_type in ['limit'] and qty > 0:
            book[side].append({
                'id': order_id,
                'price': price,
                'qty': qty,
                'arrival_time': order_state[order_id]['arrival_time']
            })
            order_state[order_id]['status'] = 'resting'
        elif qty > 0:
            order_state[order_id]['status'] = 'filled'
        else:
            order_state[order_id]['status'] = 'filled'

        if side == 'buy':
            book['buy'].sort(key=lambda o: (-o['price'], o['arrival_time']))
        else:
            book['sell'].sort(key=lambda o: (o['price'], o['arrival_time']))

    return trades

